import itertools
import json

givens = [
    ("tmi’gn", "dəmīgən"),
    ("an’stawteg", "anəstawtek"),
    ("gjiansale’wit", "əkciansalēwit"),
    ("mgumie’jo’tlatl", "əmkumiējōdəladəl"),
    ("amqwanji’j", "amxʷancīc"),
    ("e’jnt", "ējənt"),
    ("tplutaqan", "ətpəludaɣan"),
    ("ge’gwising", "gēgʷisink"),
    ("lnu’sgw", "lənūskw"),
    ("g’p’ta’q", "gəbədāx"),
    ("epsaqtejg", "epsaxteck"),
]

vowels = set("aeiouə")
sonorants = set("mnlwj")
underlying = {"g": "k", "j": "c", "q": "x"}

def is_vowel(token):
    return bool(token) and token[0] in vowels

def transcribe(word):
    tokens = []
    for letter in word:
        if letter == "’":
            if not tokens:
                return None
            if is_vowel(tokens[-1]) and tokens[-1] != "ə":
                tokens[-1] += "\u0304"
            else:
                tokens.append("ə")
        else:
            tokens.append(underlying.get(letter, letter))

    # Initial clusters with an obstruent as their second member.
    if (len(tokens) >= 2
            and not is_vowel(tokens[0])
            and not is_vowel(tokens[1])
            and tokens[1] not in set("mnlw")):
        tokens.insert(0, "ə")

    expanded = []
    for i, token in enumerate(tokens):
        expanded.append(token)
        if (i + 1 < len(tokens)
                and not is_vowel(token)
                and tokens[i + 1] in set("mnl")):
            expanded.append("ə")

    voiced = {"p": "b", "t": "d", "k": "g", "c": "j"}
    result = []
    for i, token in enumerate(expanded):
        previous = expanded[i - 1] if i else None
        following = expanded[i + 1] if i + 1 < len(expanded) else None
        next_sound = following
        if (following == "w" and i + 2 < len(expanded)
                and token in {"k", "x"}):
            next_sound = expanded[i + 2]

        can_voice = (
            (previous is None or is_vowel(previous))
            and next_sound is not None
            and (is_vowel(next_sound) or next_sound in sonorants)
        )
        if token in voiced and can_voice:
            token = voiced[token]
        elif token == "x" and can_voice:
            token = "ɣ"
        result.append(token)

    output = []
    i = 0
    while i < len(result):
        if (i + 2 < len(result)
                and result[i] in {"k", "g", "x", "ɣ"}
                and result[i + 1] == "w"
                and is_vowel(result[i + 2])):
            output.append(result[i] + "ʷ")
            i += 2
        else:
            output.append(result[i])
            i += 1
    return "".join(output)

if not all(transcribe(word) == sound for word, sound in givens):
    print("UNSUPPORTED")
else:
    target = "alaptək"

    # Invert the segment correspondences, then exhaustively test every
    # possible apostrophe placement. Schwa may instead be epenthetic.
    alphabet = sorted({c for word, _ in givens for c in word if c != "’"})
    inverse = {}
    for letter in alphabet:
        segment = underlying.get(letter, letter)
        inverse.setdefault(segment, []).append(letter)

    segment_choices = [inverse.get(c, []) for c in target if c != "ə"]
    answers = set()
    tested = 0

    if all(segment_choices):
        for base_tuple in itertools.product(*segment_choices):
            for marks in itertools.product((False, True), repeat=len(base_tuple)):
                candidate = "".join(
                    letter + ("’" if marked else "")
                    for letter, marked in zip(base_tuple, marks)
                )
                tested += 1
                if transcribe(candidate) == target:
                    answers.add(candidate)

    if len(answers) != 1:
        print("UNSUPPORTED")
    else:
        answer = next(iter(answers))
        print(json.dumps({
            "final_answer": answer,
            "evidence": {
                "given_transcriptions_verified": len(givens),
                "candidates_tested": tested,
                "matching_candidates": len(answers),
                "computed_transcription": transcribe(answer)
            }
        }, ensure_ascii=False, separators=(",", ":")))
